import{_ as n,c as i,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Nutzungsbedingungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/terms.md","filePath":"de/guide/terms.md","lastUpdated":1793163976000}'),r={name:"de/guide/terms.md"};function u(l,e,d,h,s,g){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="nutzungsbedingungen" tabindex="-1">Nutzungsbedingungen <a class="header-anchor" href="#nutzungsbedingungen" aria-label="Permalink to &quot;Nutzungsbedingungen&quot;">​</a></h1><p>Diese Bedingungen regeln Ihre Nutzung von NueZip. Durch Herunterladen, Installieren oder Nutzen von NueZip stimmen Sie diesen Bedingungen zu. Wenn Sie nicht zustimmen, nutzen Sie die Anwendung nicht.</p><h2 id="lizenz-und-nutzung" tabindex="-1">Lizenz und Nutzung <a class="header-anchor" href="#lizenz-und-nutzung" aria-label="Permalink to &quot;Lizenz und Nutzung&quot;">​</a></h2><p>NueZip wird unter den Lizenzbedingungen bereitgestellt, die jeder Version beiliegen. Ihnen wird eine begrenzte, nicht-exklusive, nicht-übertragbare Lizenz zur Nutzung der Anwendung auf Ihrem Mac gemäß den Lizenzbedingungen eingeräumt.</p><h2 id="nur-lokal-betrieb" tabindex="-1">Nur-lokal-Betrieb <a class="header-anchor" href="#nur-lokal-betrieb" aria-label="Permalink to &quot;Nur-lokal-Betrieb&quot;">​</a></h2><p>NueZip ist eine vollständig offline arbeitende Anwendung. Alle Archivvorgänge werden lokal auf Ihrem Gerät ausgeführt. Es werden keine Dateien, Metadaten oder persönlichen Daten an externe Server übertragen.</p><h2 id="kaufe" tabindex="-1">Käufe <a class="header-anchor" href="#kaufe" aria-label="Permalink to &quot;Käufe&quot;">​</a></h2><p>Eine Vollversionslizenz ist über einen einmaligen Kauf im Mac App Store erhältlich. Alle Käufe werden von Apple abgewickelt. NueZip verarbeitet keine Zahlungsinformationen. Die Wiederherstellung von Käufen wird bei Neuinstallationen unterstützt.</p><h2 id="benutzerpflichten" tabindex="-1">Benutzerpflichten <a class="header-anchor" href="#benutzerpflichten" aria-label="Permalink to &quot;Benutzerpflichten&quot;">​</a></h2><ul><li>Nutzen Sie NueZip rechtmäßig und in Übereinstimmung mit geltenden Regeln.</li><li>Versuchen Sie nicht, die App entgegen der Lizenz zu dekompilieren, reversezukonstruieren oder zu modifizieren.</li><li>Nutzen Sie NueZip nicht, um Urheberrechtsschutz oder DRM auf Archiven zu umgehen.</li></ul><h2 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to &quot;Datenschutz&quot;">​</a></h2><p>Bitte lesen Sie die <a href="/de/guide/privacy.html">Datenschutzerklärung</a> für Informationen zu Datenpraktiken und Privatsphäre.</p><h2 id="keine-gewahrleistung" tabindex="-1">Keine Gewährleistung <a class="header-anchor" href="#keine-gewahrleistung" aria-label="Permalink to &quot;Keine Gewährleistung&quot;">​</a></h2><p>NueZip wird „wie besehen&quot; ohne Gewährleistungen irgendeiner Art bereitgestellt. Soweit gesetzlich zulässig, schließen die Maintainer alle Gewährleistungen aus, ob ausdrücklich, stillschweigend, gesetzlich oder anderweitig, einschließlich der Handelsüblichkeit und der Eignung für einen bestimmten Zweck.</p><h2 id="haftungsbeschrankung" tabindex="-1">Haftungsbeschränkung <a class="header-anchor" href="#haftungsbeschrankung" aria-label="Permalink to &quot;Haftungsbeschränkung&quot;">​</a></h2><p>Soweit gesetzlich zulässig, haften die Maintainer nicht für indirekte, zufällige, besondere, Folge- oder exemplarische Schäden, die aus Ihrer Nutzung der Anwendung entstehen.</p><h2 id="beendigung" tabindex="-1">Beendigung <a class="header-anchor" href="#beendigung" aria-label="Permalink to &quot;Beendigung&quot;">​</a></h2><p>Die Ihnen eingeräumten Rechte enden automatisch, wenn Sie diese Bedingungen nicht einhalten.</p><h2 id="anderungen" tabindex="-1">Änderungen <a class="header-anchor" href="#anderungen" aria-label="Permalink to &quot;Änderungen&quot;">​</a></h2><p>Wir können diese Bedingungen von Zeit zu Zeit aktualisieren. Die fortgesetzte Nutzung nach Änderungen gilt als Annahme der überarbeiteten Bedingungen.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Für Fragen zu diesen Bedingungen öffnen Sie ein Issue im Projekt-Repository: <code>https://github.com/nuezip/nuezip/issues</code></p><p>Oder schreiben Sie uns eine E-Mail an: <a href="mailto:nuezip@w3cub.com" target="_blank" rel="noreferrer">nuezip@w3cub.com</a></p><p><em>Zuletzt aktualisiert: 14. Juni 2026</em></p>',24)])])}const z=n(r,[["render",u]]);export{c as __pageData,z as default};
